INSERT INTO employees(code,name,site) VALUES('EMP-01','Aroha Chen','Hamilton'),('EMP-02','Ben Patel','Hamilton'),('EMP-03','Mara Ngata','Hamilton'),('EMP-04','Ben Wilson','Tauranga') ON CONFLICT DO NOTHING;
INSERT INTO roles(code,name) VALUES('ROLE-01','Packing operator'),('ROLE-02','Dispatch operator') ON CONFLICT DO NOTHING;
INSERT INTO skills(code,name) VALUES('SK-01','Machine isolation'),('SK-02','Packing quality check'),('SK-03','Dispatch verification') ON CONFLICT DO NOTHING;
INSERT INTO requirements(code,role_id,skill_id,minimum_level,minimum_cover) SELECT v.code,ro.id,s.id,3,2 FROM (VALUES('REQ-01','ROLE-01','SK-01'),('REQ-02','ROLE-01','SK-02'),('REQ-03','ROLE-02','SK-03')) v(code,role,skill) JOIN roles ro ON ro.code=v.role JOIN skills s ON s.code=v.skill ON CONFLICT DO NOTHING;
INSERT INTO assignments(code,employee_id,role_id,starts_on) SELECT 'AS-'||e.code,e.id,ro.id,CURRENT_DATE-90 FROM employees e JOIN roles ro ON ro.code=CASE WHEN e.code='EMP-04' THEN 'ROLE-02' ELSE 'ROLE-01' END ON CONFLICT DO NOTHING;
INSERT INTO results(code,employee_id,skill_id,level,assessed_on,expires_on,assessor,evidence,status) SELECT v.code,e.id,s.id,v.level,CURRENT_DATE-60,CURRENT_DATE+v.days,'Demo assessor',v.evidence,v.status FROM (VALUES ('RES-01','EMP-01','SK-01',4,12,'demo-only:assessment-1','approved'),('RES-02','EMP-01','SK-02',4,180,'demo-only:assessment-2','approved'),('RES-03','EMP-02','SK-01',3,-4,'demo-only:assessment-3','approved'),('RES-04','EMP-02','SK-02',2,90,'demo-only:assessment-4','approved'),('RES-05','EMP-03','SK-01',4,90,'demo-only:assessment-5','pending'),('RES-06','EMP-04','SK-03',3,90,'','approved')) v(code,employee,skill,level,days,evidence,status) JOIN employees e ON e.code=v.employee JOIN skills s ON s.code=v.skill ON CONFLICT DO NOTHING;
INSERT INTO training(code,employee_id,skill_id,due_on,owner) SELECT 'TRAIN-01',e.id,s.id,CURRENT_DATE-5,'Jess' FROM employees e,skills s WHERE e.code='EMP-02' AND s.code='SK-01' ON CONFLICT DO NOTHING;
